"use client";

import * as React from "react";
import { AlertDialog as AlertDialogPrimitive } from "@base-ui/react/alert-dialog";

import { cn } from "@/lib/utils";
import { buttonVariants } from "./button";
import { cardSlab } from "./_shared";

// Base UI accepts a state function for className; these wrappers merge it with
// cn(), so they take a plain string.
type WithClassName<P> = Omit<P, "className"> & { className?: string };

/** Mallow AlertDialog root: a modal that waits for a decision. */
const AlertDialog = AlertDialogPrimitive.Root;

/** The control that opens the alert dialog. */
const AlertDialogTrigger = AlertDialogPrimitive.Trigger;

/** Moves the alert dialog to the end of the document body. */
const AlertDialogPortal = AlertDialogPrimitive.Portal;

/** The soft plum scrim behind the alert, which does not dismiss it on click. */
const AlertDialogOverlay = React.forwardRef<HTMLDivElement, WithClassName<AlertDialogPrimitive.Backdrop.Props>>(
  ({ className, ...props }, ref) => (
    <AlertDialogPrimitive.Backdrop
      ref={ref}
      data-slot="alert-dialog-overlay"
      className={cn(
        "fixed inset-0 z-50 bg-(--scrim)",
        "transition-opacity duration-base ease-(--ease-out)",
        "data-[starting-style]:opacity-0 data-[ending-style]:opacity-0",
        className,
      )}
      {...props}
    />
  ),
);
AlertDialogOverlay.displayName = "AlertDialogOverlay";

/** Mallow alert window: the white card, 28rem wide at most, with no close button so the reader answers. */
const AlertDialogContent = React.forwardRef<HTMLDivElement, WithClassName<AlertDialogPrimitive.Popup.Props>>(
  ({ className, ...props }, ref) => (
    <AlertDialogPortal>
      <AlertDialogOverlay />
      <AlertDialogPrimitive.Popup
        ref={ref}
        data-slot="alert-dialog-content"
        className={cn(
          "fixed inset-x-4 top-1/2 z-50 mx-auto grid max-w-md -translate-y-1/2 gap-5",
          "rounded-4xl p-7 outline-none",
          cardSlab,
          "transition-[opacity,scale] duration-base ease-(--ease-out)",
          "data-[starting-style]:scale-95 data-[starting-style]:opacity-0",
          "data-[ending-style]:scale-95 data-[ending-style]:opacity-0",
          className,
        )}
        {...props}
      />
    </AlertDialogPortal>
  ),
);
AlertDialogContent.displayName = "AlertDialogContent";

/** The question block at the top of the alert. */
const AlertDialogHeader = ({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) => (
  <div data-slot="alert-dialog-header" className={cn("flex flex-col gap-1.5 text-start", className)} {...props} />
);
AlertDialogHeader.displayName = "AlertDialogHeader";

/** The answer row, with the confirm button above Cancel on a phone and both in a row from the small breakpoint. */
const AlertDialogFooter = ({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) => (
  <div
    data-slot="alert-dialog-footer"
    className={cn("flex flex-col-reverse gap-3 sm:flex-row sm:justify-end", className)}
    {...props}
  />
);
AlertDialogFooter.displayName = "AlertDialogFooter";

/** The alert question in medium weight ink. */
const AlertDialogTitle = React.forwardRef<HTMLHeadingElement, WithClassName<AlertDialogPrimitive.Title.Props>>(
  ({ className, ...props }, ref) => (
    <AlertDialogPrimitive.Title
      ref={ref}
      data-slot="alert-dialog-title"
      className={cn("text-xl font-medium leading-tight tracking-tight text-foreground", className)}
      {...props}
    />
  ),
);
AlertDialogTitle.displayName = "AlertDialogTitle";

/** What happens if the reader confirms, in muted text. */
const AlertDialogDescription = React.forwardRef<
  HTMLParagraphElement,
  WithClassName<AlertDialogPrimitive.Description.Props>
>(({ className, ...props }, ref) => (
  <AlertDialogPrimitive.Description
    ref={ref}
    data-slot="alert-dialog-description"
    className={cn("text-sm leading-relaxed text-muted-foreground", className)}
    {...props}
  />
));
AlertDialogDescription.displayName = "AlertDialogDescription";

/** The confirm button, in the solid violet primary. */
const AlertDialogAction = React.forwardRef<HTMLButtonElement, WithClassName<AlertDialogPrimitive.Close.Props>>(
  ({ className, ...props }, ref) => (
    <AlertDialogPrimitive.Close
      ref={ref}
      data-slot="alert-dialog-action"
      className={cn(buttonVariants({ variant: "default" }), className)}
      {...props}
    />
  ),
);
AlertDialogAction.displayName = "AlertDialogAction";

/** The way out, in the quiet white secondary beside the confirm button. */
const AlertDialogCancel = React.forwardRef<HTMLButtonElement, WithClassName<AlertDialogPrimitive.Close.Props>>(
  ({ className, ...props }, ref) => (
    <AlertDialogPrimitive.Close
      ref={ref}
      data-slot="alert-dialog-cancel"
      className={cn(buttonVariants({ variant: "secondary" }), className)}
      {...props}
    />
  ),
);
AlertDialogCancel.displayName = "AlertDialogCancel";

export {
  AlertDialog,
  AlertDialogPortal,
  AlertDialogOverlay,
  AlertDialogTrigger,
  AlertDialogContent,
  AlertDialogHeader,
  AlertDialogFooter,
  AlertDialogTitle,
  AlertDialogDescription,
  AlertDialogAction,
  AlertDialogCancel,
};
